1	/**
2	 * Tiny, dependency-free, safe Markdown → HTML renderer.
3	 *
4	 * Deliberately minimal: it supports the subset used by our internal docs
5	 * (headings, bold/italic, inline code, fenced/indented code blocks, unordered &
6	 * ordered lists, blockquotes, links, horizontal rules, paragraphs). It is NOT a
7	 * general CommonMark implementation.
8	 *
9	 * Safety: ALL raw text is HTML-escaped before any markup is emitted, so the
10	 * rendered document can never inject markup or scripts from the source file.
11	 * Link targets are whitelisted to http(s)/mailto/relative/anchor URLs; anything
12	 * else (e.g. javascript:) is dropped and rendered as plain text.
13	 */
14	
15	function escapeHtml(s: string): string {
16	  return s
17	    .replace(/&/g, "&amp;")
18	    .replace(/</g, "&lt;")
19	    .replace(/>/g, "&gt;")
20	    .replace(/"/g, "&quot;")
21	    .replace(/'/g, "&#39;");
22	}
23	
24	function safeUrl(url: string): string | null {
25	  const u = url.trim();
26	  if (/^(https?:\/\/|mailto:)/i.test(u)) return u;
27	  if (u.startsWith("/") || u.startsWith("#")) return u;
28	  return null;
29	}
30	
31	/** Inline formatting on a single (already block-stripped) line of raw text. */
32	function renderInline(raw: string): string {
33	  // Pull out inline code first so ** / * / [] inside code stay literal.
34	  const codes: string[] = [];
35	  let text = raw.replace(/`([^`]+)`/g, (_m, code) => {
36	    codes.push(`<code class="rounded bg-white/[0.07] px-1.5 py-0.5 text-[0.85em] text-brand-200">${escapeHtml(code)}</code>`);
37	    return `�${codes.length - 1}�`;
38	  });
39	
40	  text = escapeHtml(text);
41	
42	  // Links: [label](url) — escapeHtml already ran, so brackets/parens are intact.
43	  text = text.replace(/\[([^\]]+)\]\(([^)]+)\)/g, (m, label, url) => {
44	    const href = safeUrl(url);
45	    if (!href) return label;
46	    return `<a href="${escapeHtml(href)}" class="text-brand-300 underline decoration-brand-500/40 underline-offset-2 hover:text-brand-200" target="_blank" rel="noreferrer">${label}</a>`;
47	  });
48	
49	  text = text.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
50	  text = text.replace(/(^|[^*])\*([^*]+)\*/g, "$1<em>$2</em>");
51	  text = text.replace(/(^|[^_])_([^_]+)_/g, "$1<em>$2</em>");
52	
53	  // Restore code placeholders.
54	  text = text.replace(/�(\d+)�/g, (_m, i) => codes[Number(i)]);
55	  return text;
56	}
57	
58	/** Render Markdown source to a sanitized HTML string. */
59	export function renderMarkdown(src: string): string {
60	  const lines = src.replace(/\r\n/g, "\n").split("\n");
61	  const out: string[] = [];
62	  let i = 0;
63	
64	  const flushList = (items: string[], ordered: boolean) => {
65	    if (items.length === 0) return;
66	    const tag = ordered ? "ol" : "ul";
67	    const cls = ordered ? "ml-5 list-decimal space-y-1" : "ml-5 list-disc space-y-1";
68	    out.push(`<${tag} class="${cls} text-slate-300">${items.map((it) => `<li>${renderInline(it)}</li>`).join("")}</${tag}>`);
69	  };
70	
71	  while (i < lines.length) {
72	    const line = lines[i];
73	
74	    // Fenced code block.
75	    const fence = line.match(/^```(.*)$/);
76	    if (fence) {
77	      const body: string[] = [];
78	      i++;
79	      while (i < lines.length && !/^```/.test(lines[i])) {
80	        body.push(lines[i]);
81	        i++;
82	      }
83	      i++; // consume closing fence
84	      out.push(
85	        `<pre class="overflow-x-auto rounded-xl border border-white/[0.07] bg-navy-950/70 p-4 text-[13px] leading-relaxed text-slate-200"><code>${escapeHtml(body.join("\n"))}</code></pre>`
86	      );
87	      continue;
88	    }
89	
90	    // Blank line.
91	    if (line.trim() === "") {
92	      i++;
93	      continue;
94	    }
95	
96	    // Horizontal rule.
97	    if (/^(-{3,}|\*{3,}|_{3,})$/.test(line.trim())) {
98	      out.push('<hr class="my-6 border-white/[0.08]" />');
99	      i++;
100	      continue;
101	    }
102	
103	    // Heading.
104	    const h = line.match(/^(#{1,6})\s+(.*)$/);
105	    if (h) {
106	      const level = h[1].length;
107	      const sizes: Record<number, string> = {
108	        1: "mt-2 text-2xl font-bold tracking-tight text-white",
109	        2: "mt-8 text-xl font-bold tracking-tight text-white",
110	        3: "mt-6 text-lg font-semibold text-white",
111	        4: "mt-5 text-base font-semibold text-slate-100",
112	        5: "mt-4 text-sm font-semibold text-slate-200",
113	        6: "mt-4 text-sm font-semibold text-slate-300",
114	      };
115	      out.push(`<h${level} class="${sizes[level] ?? sizes[6]}">${renderInline(h[2])}</h${level}>`);
116	      i++;
117	      continue;
118	    }
119	
120	    // Blockquote.
121	    if (/^>\s?/.test(line)) {
122	      const body: string[] = [];
123	      while (i < lines.length && /^>\s?/.test(lines[i])) {
124	        body.push(lines[i].replace(/^>\s?/, ""));
125	        i++;
126	      }
127	      out.push(`<blockquote class="border-l-2 border-brand-500/50 pl-4 text-slate-400">${renderInline(body.join(" "))}</blockquote>`);
128	      continue;
129	    }
130	
131	    // Unordered list.
132	    if (/^\s*[-*+]\s+/.test(line)) {
133	      const items: string[] = [];
134	      while (i < lines.length && /^\s*[-*+]\s+/.test(lines[i])) {
135	        items.push(lines[i].replace(/^\s*[-*+]\s+/, ""));
136	        i++;
137	      }
138	      flushList(items, false);
139	      continue;
140	    }
141	
142	    // Ordered list.
143	    if (/^\s*\d+\.\s+/.test(line)) {
144	      const items: string[] = [];
145	      while (i < lines.length && /^\s*\d+\.\s+/.test(lines[i])) {
146	        items.push(lines[i].replace(/^\s*\d+\.\s+/, ""));
147	        i++;
148	      }
149	      flushList(items, true);
150	      continue;
151	    }
152	
153	    // GitHub-style table: a header row, a `| --- | :--: |` delimiter row, then
154	    // body rows. Without this the delimiter row and every cell collapse into the
155	    // paragraph fallback and the reader gets a run-on line of pipe characters —
156	    // which is exactly how every table in DOCUMENTATION.md rendered at
157	    // /admin/docs until this was added. Alignment markers are honoured.
158	    if (/^\s*\|/.test(line) && i + 1 < lines.length && /^\s*\|?[\s:|-]*-[\s:|-]*\|?\s*$/.test(lines[i + 1]) && lines[i + 1].includes("-")) {
159	      const cells = (row: string) =>
160	        row.trim().replace(/^\||\|$/g, "").split("|").map((c) => c.trim());
161	      const headers = cells(line);
162	      const aligns = cells(lines[i + 1]).map((c) =>
163	        /^:-+:$/.test(c) ? "center" : /^-+:$/.test(c) ? "right" : "left"
164	      );
165	      i += 2;
166	      const rows: string[][] = [];
167	      while (i < lines.length && /^\s*\|/.test(lines[i]) && lines[i].trim() !== "") {
168	        rows.push(cells(lines[i]));
169	        i++;
170	      }
171	      const align = (n: number) => `text-${aligns[n] ?? "left"}`;
172	      const head = headers
173	        .map((hCell, n) => `<th class="border-b border-white/[0.12] px-3 py-2 font-semibold text-white ${align(n)}">${renderInline(hCell)}</th>`)
174	        .join("");
175	      const body = rows
176	        .map(
177	          (r) =>
178	            `<tr class="border-b border-white/[0.06] last:border-0">${headers
179	              .map((_h, n) => `<td class="px-3 py-2 align-top text-slate-300 ${align(n)}">${renderInline(r[n] ?? "")}</td>`)
180	              .join("")}</tr>`
181	        )
182	        .join("");
183	      out.push(
184	        `<div class="my-4 overflow-x-auto rounded-xl border border-white/[0.07]">` +
185	          `<table class="w-full border-collapse text-left text-[13px]">` +
186	          `<thead><tr>${head}</tr></thead><tbody>${body}</tbody></table></div>`
187	      );
188	      continue;
189	    }
190	
191	    // Paragraph: gather consecutive non-blank, non-structural lines.
192	    const para: string[] = [];
193	    while (
194	      i < lines.length &&
195	      lines[i].trim() !== "" &&
196	      !/^```/.test(lines[i]) &&
197	      !/^(#{1,6})\s/.test(lines[i]) &&
198	      !/^>\s?/.test(lines[i]) &&
199	      !/^\s*[-*+]\s+/.test(lines[i]) &&
200	      !/^\s*\d+\.\s+/.test(lines[i]) &&
201	      !/^(-{3,}|\*{3,}|_{3,})$/.test(lines[i].trim())
202	    ) {
203	      para.push(lines[i]);
204	      i++;
205	    }
206	    out.push(`<p class="leading-relaxed text-slate-300">${renderInline(para.join(" "))}</p>`);
207	  }
208	
209	  return out.join("\n");
210	}
